using System;using System.Net;using System.Net.Sockets;using System.Net.NetworkInformation;using System.Collections.Generic;using System.Threading.Tasks;using System.Text;using System.Web.Script.Serialization;
sealed class DiscoveredHost{public string Name,Url;public override string ToString(){return Name+" — "+Url;}}
static class LanDiscovery{
 public static IPAddress Broadcast(IPAddress ip,IPAddress mask){var a=ip.GetAddressBytes();var m=mask.GetAddressBytes();for(int i=0;i<4;i++)a[i]=(byte)(a[i]|(~m[i]&255));return new IPAddress(a);}
 public static List<DiscoveredHost> Find(){var jobs=new List<Task<List<DiscoveredHost>>>();foreach(var nic in NetworkInterface.GetAllNetworkInterfaces()){if(nic.OperationalStatus!=OperationalStatus.Up||nic.NetworkInterfaceType==NetworkInterfaceType.Loopback)continue;foreach(var item in nic.GetIPProperties().UnicastAddresses)if(item.Address.AddressFamily==AddressFamily.InterNetwork&&item.IPv4Mask!=null){var local=item.Address;var broadcast=Broadcast(local,item.IPv4Mask);jobs.Add(Task.Run(()=>Probe(local,broadcast)));}}Task.WaitAll(jobs.ToArray());var result=new List<DiscoveredHost>();foreach(var job in jobs)foreach(var item in job.Result)if(!result.Exists(x=>x.Url==item.Url))result.Add(item);return result;}
 public static List<DiscoveredHost> Probe(IPAddress local,IPAddress broadcast){var result=new List<DiscoveredHost>();try{using(var udp=new UdpClient(new IPEndPoint(local,0))){udp.EnableBroadcast=true;udp.Client.ReceiveTimeout=250;var bytes=Encoding.UTF8.GetBytes("{\"service\":\"lifeac-discover\"}");var until=DateTime.UtcNow.AddSeconds(5);var next=DateTime.MinValue;while(DateTime.UtcNow<until){if(DateTime.UtcNow>=next){udp.Send(bytes,bytes.Length,new IPEndPoint(broadcast,47833));next=DateTime.UtcNow.AddSeconds(1);}try{var peer=new IPEndPoint(IPAddress.Any,0);var packet=udp.Receive(ref peer);var host=Parse(packet,peer.Address);if(host!=null&&!result.Exists(x=>x.Url==host.Url))result.Add(host);}catch(SocketException){}}}}catch{}return result;}
 public static DiscoveredHost Parse(byte[] packet,IPAddress peer){if(packet.Length>4096)return null;try{var info=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(packet));Uri url;if(Convert.ToString(info["service"])!="lifeac-lighting"||!Uri.TryCreate(Convert.ToString(info["url"]),UriKind.Absolute,out url)||url.Scheme!="https"||url.Host!=peer.ToString()||url.AbsolutePath!="/"||!String.IsNullOrEmpty(url.UserInfo)||!String.IsNullOrEmpty(url.Query)||!String.IsNullOrEmpty(url.Fragment))return null;return new DiscoveredHost{Url=url.AbsoluteUri,Name=Convert.ToString(info["name"])+" · "+Convert.ToString(info["role"])};}catch{return null;}}
}
